#!/usr/bin/env bash
set -euo pipefail
sha="$(git rev-parse HEAD)"
[[ "$sha" == "$MERGED_SHA" && "$PR_NUMBER" =~ ^[0-9]+$ ]]
git fetch origin main
git merge-base --is-ancestor "$sha" origin/main
short="$(git rev-parse --short=12 HEAD)"
apk="dist/GalleryBridge-$short.apk"
sum="$apk.sha256"
test -s "$apk" && test -s "$sum"
(cd dist && sha256sum -c "$(basename "$sum")")
notes="$(mktemp)"
trap 'rm -f -- "$notes"' EXIT
printf 'Commit: %s\n\nPR: #%s\n\nSigned APK; JVM tests, Android lint, Detekt and builds passed.\nVerify the SHA-256 checksum before installing.\n' "$sha" "$PR_NUMBER" > "$notes"
if [[ "$PRERELEASE" == true ]]; then
  tag="pre-pr$PR_NUMBER-$short"
  if gh release view "$tag" --json tagName >/dev/null 2>&1; then
    git fetch origin "refs/tags/$tag"
    [[ "$(git rev-parse 'FETCH_HEAD^{commit}')" == "$sha" ]]
    gh release upload "$tag" "$apk" "$sum" --clobber
  else
    gh release create "$tag" "$apk" "$sum" --target "$sha" --prerelease --latest=false --title "GalleryBridge preview $short" --notes-file "$notes"
  fi
else
  tag=latest
  old="$(git ls-remote --refs origin refs/tags/latest | awk '{print $1}')"
  if [[ -n "$old" ]]; then
    git fetch origin refs/tags/latest
    old_commit="$(git rev-parse 'FETCH_HEAD^{commit}')"
    if git merge-base --is-ancestor "$sha" "$old_commit" && [[ "$sha" != "$old_commit" ]]; then
      echo "Skipping older stable release: latest already points to a newer commit"
      exit 0
    fi
    git merge-base --is-ancestor "$old_commit" "$sha"
    # Upload new unique assets before moving latest. Never delete old assets first.
    if gh release view "$tag" --json tagName >/dev/null 2>&1; then
      gh release upload "$tag" "$apk" "$sum" --clobber
    else
      [[ "$old_commit" == "$sha" ]] || { echo "::error::latest tag exists without release; inspect manually"; exit 1; }
      gh release create "$tag" "$apk" "$sum" --verify-tag --latest --title "GalleryBridge latest" --notes-file "$notes"
    fi
    if [[ "$old_commit" != "$sha" ]]; then
      git push --force-with-lease="refs/tags/latest:$old" origin "$sha:refs/tags/latest"
    fi
    gh release edit "$tag" --latest --prerelease=false --title "GalleryBridge latest" --notes-file "$notes"
    # Only remove assets generated by this workflow, after new assets and tag succeeded.
    while IFS= read -r name; do
      if [[ "$name" =~ ^GalleryBridge-[0-9a-f]{12}\.apk(\.sha256)?$ && "$name" != "$(basename "$apk")" && "$name" != "$(basename "$sum")" ]]; then
        gh release delete-asset "$tag" "$name" --yes
      fi
    done < <(gh release view "$tag" --json assets --jq '.assets[].name')
  else
    gh release create "$tag" "$apk" "$sum" --target "$sha" --latest --title "GalleryBridge latest" --notes-file "$notes"
  fi
fi
gh release view "$tag" --json url,tagName,isPrerelease
